import React, { useState } from 'react';
import { motion } from 'framer-motion';
import { useTheme } from '../contexts/ThemeContext';
import { 
  LineChart, Line, BarChart, Bar, PieChart, Pie, 
  Cell, XAxis, YAxis, CartesianGrid, Tooltip, 
  Legend, ResponsiveContainer 
} from 'recharts';

const Statistics = () => {
  const { theme } = useTheme();
  const [timeRange, setTimeRange] = useState('week'); // 'day', 'week', 'month', 'year'
  
  const pageVariants = {
    initial: { opacity: 0, y: 20 },
    animate: { 
      opacity: 1, 
      y: 0,
      transition: { 
        duration: 0.5,
        ease: "easeOut"
      }
    },
    exit: { 
      opacity: 0,
      y: -20,
      transition: { 
        duration: 0.3 
      }
    }
  };
  
  // Sample data - this would be fetched from your backend in a real app
  const studySessionData = [
    { day: 'Monday', hours: 2.5, focusScore: 85 },
    { day: 'Tuesday', hours: 3, focusScore: 75 },
    { day: 'Wednesday', hours: 1.5, focusScore: 90 },
    { day: 'Thursday', hours: 4, focusScore: 95 },
    { day: 'Friday', hours: 2, focusScore: 80 },
    { day: 'Saturday', hours: 0.5, focusScore: 70 },
    { day: 'Sunday', hours: 3.5, focusScore: 88 },
  ];
  
  const subjectBreakdownData = [
    { name: 'Mathematics', value: 35, color: '#3B82F6' },
    { name: 'Science', value: 20, color: '#10B981' },
    { name: 'History', value: 15, color: '#F59E0B' },
    { name: 'Literature', value: 10, color: '#8B5CF6' },
    { name: 'Languages', value: 20, color: '#EC4899' },
  ];
  
  const focusTrends = [
    { time: '9 AM', focus: 75 },
    { time: '10 AM', focus: 90 },
    { time: '11 AM', focus: 85 },
    { time: '12 PM', focus: 60 },
    { time: '1 PM', focus: 50 },
    { time: '2 PM', focus: 65 },
    { time: '3 PM', focus: 80 },
    { time: '4 PM', focus: 85 },
    { time: '5 PM', focus: 75 },
  ];
  
  const totalHours = studySessionData.reduce((acc, curr) => acc + curr.hours, 0);
  const averageFocus = Math.round(studySessionData.reduce((acc, curr) => acc + curr.focusScore, 0) / studySessionData.length);
  const totalSessions = 23; // In a real app, this would be calculated from actual data
  const completedTasks = 18; // In a real app, this would be calculated from actual data

  return (
    <motion.div
      initial="initial"
      animate="animate"
      exit="exit"
      variants={pageVariants}
      className="max-w-6xl mx-auto"
    >
      <div className="mb-6 text-center">
        <h1 className={`text-4xl font-bold ${theme.text.primary}`}>
          Study Statistics
        </h1>
        <p className={`text-lg mt-2 ${theme.text.secondary}`}>
          Track your progress and visualize your study habits
        </p>
      </div>
      
      {/* Time range selector */}
      <motion.div 
        className={`p-4 rounded-xl ${theme.card} backdrop-blur-lg shadow-lg mb-6 flex justify-center`}
        initial={{ opacity: 0, y: -20 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ delay: 0.1 }}
      >
        <div className="inline-flex bg-gray-800 bg-opacity-50 rounded-lg p-1">
          {['day', 'week', 'month', 'year'].map((range) => (
            <motion.button
              key={range}
              className={`px-4 py-2 rounded-lg ${timeRange === range ? 'bg-blue-500 text-white' : 'text-gray-300 hover:text-white'}`}
              onClick={() => setTimeRange(range)}
              whileHover={{ scale: 1.05 }}
              whileTap={{ scale: 0.95 }}
            >
              {range.charAt(0).toUpperCase() + range.slice(1)}
            </motion.button>
          ))}
        </div>
      </motion.div>
      
      {/* Stats overview */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4 mb-6">
        {[
          { label: 'Total Hours', value: `${totalHours}h`, icon: 'clock', color: 'from-blue-500 to-blue-700' },
          { label: 'Avg. Focus', value: `${averageFocus}%`, icon: 'target', color: 'from-green-500 to-green-700' },
          { label: 'Sessions', value: totalSessions, icon: 'calendar', color: 'from-purple-500 to-purple-700' },
          { label: 'Tasks Done', value: completedTasks, icon: 'check', color: 'from-orange-500 to-orange-700' },
        ].map((stat, index) => (
          <motion.div
            key={stat.label}
            className={`${theme.card} rounded-xl shadow-lg p-6 relative overflow-hidden`}
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: 0.1 + index * 0.1 }}
          >
            <div className={`absolute inset-0 bg-gradient-to-br ${stat.color} opacity-10`}></div>
            <div className="flex items-center justify-between z-10 relative">
              <div>
                <p className={`text-sm ${theme.text.secondary}`}>{stat.label}</p>
                <p className={`text-3xl font-bold ${theme.text.primary}`}>{stat.value}</p>
              </div>
              <div className={`w-12 h-12 rounded-full flex items-center justify-center bg-gradient-to-br ${stat.color}`}>
                {stat.icon === 'clock' && (
                  <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" />
                  </svg>
                )}
                {stat.icon === 'target' && (
                  <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12l2 2 4-4m5.618-4.016A11.955 11.955 0 0112 2.944a11.955 11.955 0 01-8.618 3.04A12.02 12.02 0 003 9c0 5.591 3.824 10.29 9 11.622 5.176-1.332 9-6.03 9-11.622 0-1.042-.133-2.052-.382-3.016z" />
                  </svg>
                )}
                {stat.icon === 'calendar' && (
                  <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v12a2 2 0 002 2z" />
                  </svg>
                )}
                {stat.icon === 'check' && (
                  <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" />
                  </svg>
                )}
              </div>
            </div>
          </motion.div>
        ))}
      </div>
      
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6 mb-6">
        {/* Study Hours by Day */}
        <motion.div 
          className={`p-6 rounded-xl ${theme.card} backdrop-blur-lg shadow-lg`}
          initial={{ opacity: 0, x: -20 }}
          animate={{ opacity: 1, x: 0 }}
          transition={{ delay: 0.2 }}
        >
          <h2 className={`text-xl font-semibold mb-4 ${theme.text.primary}`}>Study Hours by Day</h2>
          <ResponsiveContainer width="100%" height={300}>
            <BarChart
              data={studySessionData}
              margin={{ top: 20, right: 30, left: 20, bottom: 5 }}
            >
              <CartesianGrid strokeDasharray="3 3" stroke="rgba(255,255,255,0.1)" />
              <XAxis dataKey="day" stroke="#94a3b8" />
              <YAxis stroke="#94a3b8" />
              <Tooltip 
                contentStyle={{ backgroundColor: '#1e1e2d', borderColor: '#374151', borderRadius: '6px' }}
                labelStyle={{ color: '#e2e8f0' }}
              />
              <Legend />
              <Bar dataKey="hours" name="Hours" fill="#3B82F6" radius={[4, 4, 0, 0]} animationDuration={1500} />
            </BarChart>
          </ResponsiveContainer>
        </motion.div>
        
        {/* Subject Breakdown */}
        <motion.div 
          className={`p-6 rounded-xl ${theme.card} backdrop-blur-lg shadow-lg`}
          initial={{ opacity: 0, x: 20 }}
          animate={{ opacity: 1, x: 0 }}
          transition={{ delay: 0.3 }}
        >
          <h2 className={`text-xl font-semibold mb-4 ${theme.text.primary}`}>Subject Breakdown</h2>
          <ResponsiveContainer width="100%" height={300}>
            <PieChart>
              <Pie
                data={subjectBreakdownData}
                cx="50%"
                cy="50%"
                innerRadius={60}
                outerRadius={80}
                paddingAngle={5}
                dataKey="value"
                animationDuration={1500}
                animationBegin={400}
              >
                {subjectBreakdownData.map((entry, index) => (
                  <Cell key={`cell-${index}`} fill={entry.color} />
                ))}
              </Pie>
              <Tooltip 
                contentStyle={{ backgroundColor: '#1e1e2d', borderColor: '#374151', borderRadius: '6px' }}
                labelStyle={{ color: '#e2e8f0' }}
              />
              <Legend />
            </PieChart>
          </ResponsiveContainer>
        </motion.div>
      </div>
      
      {/* Focus Trend Over Day */}
      <motion.div 
        className={`p-6 rounded-xl ${theme.card} backdrop-blur-lg shadow-lg mb-6`}
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ delay: 0.4 }}
      >
        <h2 className={`text-xl font-semibold mb-4 ${theme.text.primary}`}>Focus Trend Throughout Day</h2>
        <ResponsiveContainer width="100%" height={300}>
          <LineChart
            data={focusTrends}
            margin={{ top: 20, right: 30, left: 20, bottom: 5 }}
          >
            <CartesianGrid strokeDasharray="3 3" stroke="rgba(255,255,255,0.1)" />
            <XAxis dataKey="time" stroke="#94a3b8" />
            <YAxis stroke="#94a3b8" />
            <Tooltip 
              contentStyle={{ backgroundColor: '#1e1e2d', borderColor: '#374151', borderRadius: '6px' }}
              labelStyle={{ color: '#e2e8f0' }}
            />
            <Legend />
            <Line 
              type="monotone" 
              dataKey="focus" 
              name="Focus Level" 
              stroke="#8B5CF6" 
              strokeWidth={3}
              dot={{ fill: '#8B5CF6', r: 6 }}
              activeDot={{ r: 8 }}
              animationDuration={2000}
            />
          </LineChart>
        </ResponsiveContainer>
      </motion.div>
      
      {/* Weekly Focus Scores */}
      <motion.div 
        className={`p-6 rounded-xl ${theme.card} backdrop-blur-lg shadow-lg`}
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ delay: 0.5 }}
      >
        <h2 className={`text-xl font-semibold mb-4 ${theme.text.primary}`}>Weekly Focus Scores</h2>
        <ResponsiveContainer width="100%" height={300}>
          <BarChart
            data={studySessionData}
            margin={{ top: 20, right: 30, left: 20, bottom: 5 }}
          >
            <CartesianGrid strokeDasharray="3 3" stroke="rgba(255,255,255,0.1)" />
            <XAxis dataKey="day" stroke="#94a3b8" />
            <YAxis stroke="#94a3b8" />
            <Tooltip 
              contentStyle={{ backgroundColor: '#1e1e2d', borderColor: '#374151', borderRadius: '6px' }}
              labelStyle={{ color: '#e2e8f0' }}
            />
            <Legend />
            <Bar dataKey="focusScore" name="Focus Score" fill="#10B981" radius={[4, 4, 0, 0]} animationDuration={1500} />
          </BarChart>
        </ResponsiveContainer>
      </motion.div>
    </motion.div>
  );
};

export default Statistics; 